// The subset of BoringSSL's `bssl-sys` that the act-rs and ihat-rs BoringSSL backends use, bound
// to the BoringSSL workerd links (@ssl//:crypto). Generated by bindgen from that BoringSSL's
// headers. BIGNUM and the other handles are opaque: the backends only hold pointers to them.
// SHA256_CTX is passed by value; layout-check.c++ checks it against the header BoringSSL is built
// with, and the asserts below check these declarations against the same numbers. Regenerate with
// generate.sh after a BoringSSL update or a backend update that uses a new symbol.

#![no_std]
#![allow(non_camel_case_types, non_snake_case, reason = "BoringSSL's C names")]
#![allow(unsafe_code, reason = "FFI declarations")]


#[repr(C)] pub struct bignum_st { _unused: [u8; 0] } pub type BIGNUM = bignum_st;

#[repr(C)]
#[derive(Debug)]
pub struct bignum_ctx {
    _unused: [u8; 0],
}
pub type BN_CTX = bignum_ctx;
#[repr(C)]
#[derive(Debug)]
pub struct bn_mont_ctx_st {
    _unused: [u8; 0],
}
pub type BN_MONT_CTX = bn_mont_ctx_st;
#[repr(C)]
#[derive(Debug)]
pub struct ec_group_st {
    _unused: [u8; 0],
}
pub type EC_GROUP = ec_group_st;
#[repr(C)]
#[derive(Debug)]
pub struct ec_point_st {
    _unused: [u8; 0],
}
pub type EC_POINT = ec_point_st;
pub type SHA256_CTX = sha256_state_st;
#[repr(u32)]
#[derive(Debug, Copy, Clone, Hash, PartialEq, Eq)]
pub enum point_conversion_form_t {
    POINT_CONVERSION_COMPRESSED = 2,
    POINT_CONVERSION_UNCOMPRESSED = 4,
    POINT_CONVERSION_HYBRID = 6,
}
#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct sha256_state_st {
    pub h: [u32; 8usize],
    pub Nl: u32,
    pub Nh: u32,
    pub data: [u8; 64usize],
    pub num: ::core::ffi::c_uint,
    pub md_len: ::core::ffi::c_uint,
}
#[allow(clippy::unnecessary_operation, clippy::identity_op)]
const _: () = {
    ["Size of sha256_state_st"][::core::mem::size_of::<sha256_state_st>() - 112usize];
    ["Alignment of sha256_state_st"][::core::mem::align_of::<sha256_state_st>() - 4usize];
    ["Offset of field: sha256_state_st::h"][::core::mem::offset_of!(sha256_state_st, h) - 0usize];
    ["Offset of field: sha256_state_st::Nl"]
        [::core::mem::offset_of!(sha256_state_st, Nl) - 32usize];
    ["Offset of field: sha256_state_st::Nh"]
        [::core::mem::offset_of!(sha256_state_st, Nh) - 36usize];
    ["Offset of field: sha256_state_st::data"]
        [::core::mem::offset_of!(sha256_state_st, data) - 40usize];
    ["Offset of field: sha256_state_st::num"]
        [::core::mem::offset_of!(sha256_state_st, num) - 104usize];
    ["Offset of field: sha256_state_st::md_len"]
        [::core::mem::offset_of!(sha256_state_st, md_len) - 108usize];
};
